return [
  {
    json: {
      _smokeTest: true,
      title: 'Q3 Planning',
      start: '2026-08-03T10:00:00+02:00',
      end: '2026-08-03T11:00:00+02:00',
      attendees: ['Alice', 'Bob'],
      location: 'Zoom',
      agenda: '1. Goals\n2. Risks',
      notes: 'Optional freeform notes',
      folder: '/Work/Meetings',
    },
  },
];

const FOLDER_RE = /^(\/[A-Za-z0-9._-]+)+$/;
const DEFAULT_FOLDER = '/Work/Meetings';

const item = $input.first().json;
const body =
  item.body && typeof item.body === 'object' && !Array.isArray(item.body)
    ? item.body
    : item;

const smokeTest = Boolean(body._smokeTest);
const title = String(body.title ?? '').trim();
if (!title) {
  throw new Error('Missing required field: title');
}

let attendees = [];
if (Array.isArray(body.attendees)) {
  attendees = body.attendees.map((a) => String(a).trim()).filter(Boolean);
} else if (typeof body.attendees === 'string' && body.attendees.trim()) {
  attendees = body.attendees
    .split(',')
    .map((a) => a.trim())
    .filter(Boolean);
}

const folderRaw = String(body.folder ?? DEFAULT_FOLDER).trim().replace(/\/$/, '') || DEFAULT_FOLDER;
if (!FOLDER_RE.test(folderRaw)) {
  throw new Error(`Invalid folder "${folderRaw}". Expected /Work/Meetings`);
}

return [
  {
    json: {
      title,
      start: String(body.start ?? '').trim(),
      end: String(body.end ?? '').trim(),
      attendees,
      location: String(body.location ?? '').trim(),
      agenda: String(body.agenda ?? '').trim(),
      notes: String(body.notes ?? '').trim(),
      folder: folderRaw,
      viaWebhook: !smokeTest,
    },
  },
];

const BLANK_PAGE_B64 = "";
const BASE_CONTENT = {"cPages": {"lastOpened": {"timestamp": "0:0", "value": ""}, "original": {"timestamp": "0:0", "value": -1}, "pages": [], "uuids": [{"first": "c45bf333-c30a-59b0-b588-0b682888b306", "second": 1}]}, "coverPageNumber": -1, "customZoomCenterX": 0, "customZoomCenterY": 936, "customZoomOrientation": "portrait", "customZoomPageHeight": 1872, "customZoomPageWidth": 1404, "customZoomScale": 1, "documentMetadata": {}, "extraMetadata": {}, "fileType": "notebook", "fontName": "", "formatVersion": 2, "lineHeight": -1, "orientation": "portrait", "pageCount": 1, "pageTags": [], "tags": [], "textAlignment": "justify", "textScale": 1, "zoomMode": "bestFit"};
const STENCIL_AUTHOR_UUID_OFFSET = 58;
const PAGE_COUNT = 5;
const TEMPLATE = 'P Lines medium';
const ALPHA = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz';

const meeting = $input.first().json;

function uuid() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

function idxKey(i) {
  const num = 2330 + i - 1;
  return `${ALPHA[Math.floor(num / 62)]}${ALPHA[num % 62]}`;
}

function crc32(buf) {
  let c = ~0;
  for (let i = 0; i < buf.length; i++) {
    c ^= buf[i];
    for (let k = 0; k < 8; k++) {
      c = c & 1 ? (0xedb88320 ^ (c >>> 1)) : c >>> 1;
    }
  }
  return ~c >>> 0;
}

function u16(n) {
  const b = Buffer.alloc(2);
  b.writeUInt16LE(n, 0);
  return b;
}

function u32(n) {
  const b = Buffer.alloc(4);
  b.writeUInt32LE(n, 0);
  return b;
}

function zipStore(files) {
  const localParts = [];
  const centralParts = [];
  let offset = 0;
  for (const file of files) {
    const nameBuf = Buffer.from(file.name, 'utf8');
    const data = Buffer.from(file.data);
    const crc = crc32(data);
    const local = Buffer.concat([
      Buffer.from('PK\x03\x04'),
      u16(20),
      u16(0),
      u16(0),
      u16(0),
      u16(0),
      u32(crc),
      u32(data.length),
      u32(data.length),
      u16(nameBuf.length),
      u16(0),
      nameBuf,
      data,
    ]);
    const central = Buffer.concat([
      Buffer.from('PK\x01\x02'),
      u16(20),
      u16(20),
      u16(0),
      u16(0),
      u16(0),
      u16(0),
      u32(crc),
      u32(data.length),
      u32(data.length),
      u16(nameBuf.length),
      u16(0),
      u16(0),
      u16(0),
      u16(0),
      u32(0),
      u32(offset),
      nameBuf,
    ]);
    localParts.push(local);
    centralParts.push(central);
    offset += local.length;
  }
  const central = Buffer.concat(centralParts);
  const local = Buffer.concat(localParts);
  const end = Buffer.concat([
    Buffer.from('PK\x05\x06'),
    u16(0),
    u16(0),
    u16(files.length),
    u16(files.length),
    u32(central.length),
    u32(local.length),
    u16(0),
  ]);
  return Buffer.concat([local, central, end]);
}

function sanitizeFilename(name) {
  const ascii = String(name)
    .replace(/ß/g, 'ss')
    .replace(/ẞ/g, 'SS')
    .replace(/ä/g, 'ae')
    .replace(/ö/g, 'oe')
    .replace(/ü/g, 'ue')
    .replace(/Ä/g, 'Ae')
    .replace(/Ö/g, 'Oe')
    .replace(/Ü/g, 'Ue')
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '');
  const base =
    ascii
      .replace(/[^A-Za-z0-9._-]+/g, '-')
      .replace(/-+/g, '-')
      .replace(/^[-.]+|[-.]+$/g, '') || 'Meeting';
  return base.endsWith('.rmdoc') ? base : `${base}.rmdoc`;
}

function berlinDateTime(date) {
  return new Intl.DateTimeFormat('de-DE', {
    timeZone: 'Europe/Berlin',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
  }).format(date);
}

function patchStencil(authorUuid) {
  const page = Buffer.from(BLANK_PAGE_B64, 'base64');
  const hex = authorUuid.replace(/-/g, '');
  for (let i = 0; i < 16; i++) {
    page[STENCIL_AUTHOR_UUID_OFFSET + i] = parseInt(hex.slice(i * 2, i * 2 + 2), 16);
  }
  return page;
}

const title = String(meeting.title || 'Meeting');
const folder = String(meeting.folder || '/Work/Meetings');
const filename = sanitizeFilename(title);
const start = meeting.start ? new Date(meeting.start) : null;
const end = meeting.end ? new Date(meeting.end) : null;
const startOk = start && !Number.isNaN(start.getTime());
const endOk = end && !Number.isNaN(end.getTime());

const tags = ['meeting'];
if (startOk && endOk) tags.push(`${berlinDateTime(start)} – ${berlinDateTime(end)}`);
else if (startOk) tags.push(berlinDateTime(start));
if (meeting.location) tags.push(String(meeting.location));
if (Array.isArray(meeting.attendees) && meeting.attendees.length) {
  tags.push(meeting.attendees.join(', ').slice(0, 120));
}
if (meeting.agenda) tags.push(`Agenda: ${String(meeting.agenda).replace(/\s+/g, ' ').slice(0, 160)}`);
if (meeting.notes) tags.push(`Notes: ${String(meeting.notes).replace(/\s+/g, ' ').slice(0, 160)}`);

const authorUuid = uuid();
const docId = uuid();
const createdMs = String(Date.now());
const pages = [];
const zipFiles = [];

for (let i = 1; i <= PAGE_COUNT; i++) {
  const pageId = uuid();
  pages.push({
    id: pageId,
    idx: { timestamp: '1:2', value: idxKey(i) },
    modifed: createdMs,
    template: { timestamp: '1:1', value: TEMPLATE },
  });
  zipFiles.push({
    name: `${docId}/${pageId}.rm`,
    data: patchStencil(authorUuid),
  });
}

const content = {
  ...BASE_CONTENT,
  cPages: {
    ...BASE_CONTENT.cPages,
    pages,
    lastOpened: { timestamp: '1:1', value: pages[0].id },
    uuids: [{ first: authorUuid, second: 1 }],
  },
  pageCount: PAGE_COUNT,
  tags: tags.map((name) => ({ name })),
};

const metadata = {
  createdTime: createdMs,
  lastModified: createdMs,
  lastOpened: '0',
  lastOpenedPage: -1,
  new: true,
  parent: '',
  pinned: false,
  source: '',
  type: 'DocumentType',
  visibleName: title,
};

zipFiles.unshift(
  { name: `${docId}.content`, data: Buffer.from(JSON.stringify(content), 'utf8') },
  { name: `${docId}.metadata`, data: Buffer.from(JSON.stringify(metadata), 'utf8') },
);

const rmdoc = zipStore(zipFiles);
const binary = await this.helpers.prepareBinaryData(rmdoc, filename, 'application/zip');

return [
  {
    json: {
      title,
      filename,
      folder,
      viaWebhook: Boolean(meeting.viaWebhook),
    },
    binary: { data: binary },
  },
];

const meta = $('Build Meeting Notebook').first().json;
const item = $input.first();

item.json = {
  ...item.json,
  title: meta.title,
  filename: meta.filename,
  folder: meta.folder,
  viaWebhook: meta.viaWebhook,
};

if (item.binary?.data) {
  item.binary.data.fileName = meta.filename;
  item.binary.data.mimeType = item.binary.data.mimeType || 'application/zip';
}

return [item];
